"""Forward NVIDIA DCGM values to the existing observer; drive mock NVML only."""
import concurrent.futures, http.server, json, math, os, random, re, ssl, threading, time, urllib.request
from pathlib import Path
NODE=os.environ['NODE_NAME']; NS='karta-metrics-workloads'
IDS=json.loads(Path('/runtime/devices.json').read_text()); INDEX={v:i for i,v in enumerate(IDS)}
PAT=re.compile(r'^(DCGM_FI_DEV_[A-Z_]+)\{(.*)\} ([^ ]+)(?: .*)?$')
LABEL=re.compile(r'(\w+)=("(?:[^"\\]|\\.)*")')
CA='/var/run/secrets/kubernetes.io/serviceaccount/ca.crt'
TOKEN='/var/run/secrets/kubernetes.io/serviceaccount/token'
CTX=ssl.create_default_context(cafile=CA)
state={'body':b'', 'at':0,'error':'starting'}; lock=threading.Lock()
def get(url):
 with urllib.request.urlopen(url,timeout=3) as r:return r.read().decode()
def kube_pods():
 req=urllib.request.Request('https://kubernetes.default.svc/api/v1/namespaces/'+NS+'/pods',headers={'Authorization':'Bearer '+Path(TOKEN).read_text().strip()})
 with urllib.request.urlopen(req,context=CTX,timeout=5) as r:return json.load(r)['items']
def decode(text):
 result=[]
 for line in text.splitlines():
  m=PAT.match(line)
  if not m:continue
  labels={k:json.loads(v) for k,v in LABEL.findall(m[2])};value=float(m[3])
  if not math.isfinite(value):raise ValueError('non-finite DCGM value')
  result.append((m[1],labels,value))
 return result
def fmt(name,labels,value):return name+'{'+','.join(k+'='+json.dumps(str(v)) for k,v in sorted(labels.items()))+'} '+str(value)+'\n'
def poll():
 while True:
  try:
   live=sorted(json.loads(Path('/kubelet-devices/kubelet_internal_checkpoint').read_text())['Data']['RegisteredDevices']['nvidia.com/gpu'])
   if live!=IDS:raise ValueError('Device plugin inventory changed; restart karta-real-dcgm to rediscover IDs')
   with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
    texts=list(pool.map(get,['http://127.0.0.1:'+str(9400+i)+'/metrics' for i in range(4)]))
   now=time.time(); samples=[s for t in texts for s in decode(t)]
   names={s[0] for s in samples}|{'fake_gpu_source_sample_timestamp_seconds','fake_gpu_source_healthy','karta_dcgm_bridge_scrape_timestamp_seconds'}
   util={};out=['# TYPE '+n+' gauge\n' for n in sorted(names)]
   for name,l,v in samples:
    uid=l.get('UUID'); node=l.get('hostname',l.get('Hostname'))
    if uid not in INDEX or node!=NODE:raise ValueError('unexpected DCGM identity')
    if name=='DCGM_FI_DEV_GPU_UTIL':
     if uid in util or not 0<=v<=100:raise ValueError('invalid or duplicate device utilization')
     util[uid]=(l,v)
    normalized={**l,'node':NODE,'gpu':str(INDEX[uid]),'source':'synthetic'}
    out.append(fmt(name,normalized,v))
    if name=='DCGM_FI_DEV_GPU_UTIL':out.append(fmt('fake_gpu_source_sample_timestamp_seconds',normalized,now))
   if set(util)!=set(IDS):raise ValueError('incomplete DCGM inventory')
   # Receipt timestamps measure successful DCGM scrapes, not driver sample age.
   out.append(fmt('fake_gpu_source_healthy',{'node':NODE,'source':'synthetic'},1))
   out.append(fmt('karta_dcgm_bridge_scrape_timestamp_seconds',{'node':NODE},now))
   pods={p['metadata']['uid']:p for p in kube_pods()}; overrides=[{'version':1,'devices':{}} for _ in range(4)]
   # Dynamic 0..0 means 0..100 in mock NVML; use the static utilization field.
   for uid,(labels,_) in util.items():
    i=INDEX[uid]; pod=pods.get(labels.get('pod_uid','')); value=0;used=0
    if labels.get('namespace')==NS:
     if pod is None or pod['metadata']['name']!=labels.get('pod'):raise ValueError('DCGM Pod UID does not match Kubernetes')
     raw=pod['metadata'].get('annotations',{}).get('run.ai/simulated-gpu-utilization','0-3')
     lo,hi=map(int,raw.split('-'));assert 0<=lo<=hi<=100
     value=random.randint(lo,hi);used=12000*1048576
    overrides[i//8]['devices'][str(i%8)]={'utilization':{'gpu':value,'memory':value},'memory':{'used_bytes':used,'free_bytes':12000*1048576-used,'reserved_bytes':0}}
   for i,data in enumerate(overrides):
    path=Path('/mock-state/overrides-'+str(i)+'.yaml');tmp=path.with_suffix('.tmp');tmp.write_text(json.dumps(data));os.replace(tmp,path)
   with lock:state.update(body=''.join(out).encode(),at=now,error='')
  except Exception as e:
   with lock:state['error']=str(e)
   print('DCGM bridge:',str(e),flush=True)
  time.sleep(5)
class Handler(http.server.BaseHTTPRequestHandler):
 def do_GET(self):
  with lock:ok=not state['error'] and time.time()-state['at']<20;body=state['body'];error=state['error']
  if self.path not in ['/metrics','/healthz']:self.send_error(404);return
  self.send_response(200 if ok else 503);self.send_header('Content-Type','text/plain; version=0.0.4');self.end_headers()
  self.wfile.write(body if ok and self.path=='/metrics' else ('ok' if ok else error or 'stale').encode())
 def log_message(self,*args):pass
threading.Thread(target=poll,daemon=True).start()
http.server.ThreadingHTTPServer(('0.0.0.0',9600),Handler).serve_forever()
